def main():
    jobs=json.loads((OUT/'jobs.json').read_text())
    for j in jobs:
        desc=MONSTERS[j['id']] if j['kind']=='monster' else NPCS[j['resource']] if j['kind']=='npc' else j['observedConstraints'] if j['kind']=='monster_field' else PORTRAITS[j['portraitId']]
        n=len(j['views'])
        composition=(f'Exactly {n} independent depictions of ONE character in a single horizontal row, with wide clear transparent gap between cells. '+
                     'Left: front three-quarter view as first original; right: rear three-quarter view as second original. ' if n==2 else
                     'Exactly ONE depiction, centered, preserve original pose and crop. ')
        if j['kind']=='npc':
            composition+='Overworld Q sprite, oversized head occupying about half total height, very short torso and legs; high slight top-down view matching the original. Never use adult battle body proportions.'
        elif j['kind']=='monster_field':
            composition+='Original independent compact field composite proportions; do not scale the elaborate battle illustration or impose human head/body proportions.'
        elif j['kind']=='monster':
            composition+='Combat monster proportions remain those of original, no universal human chibi transformation. Front and back MUST be the same design with same anatomy, limb count, colors and equipment.'
        else:
            composition+='Dialogue portrait has independent natural face proportions, not a resized Q body. No border/frame.'
        prompt=f'''Use case: stylized-concept
Asset type: source-faithful hand-drawn 2D Unity RPG static design candidate for {j['name']}.
Input image 1: original low-resolution source reference; read its shape and color blocks, ignore its labels and beige background. Input image 2: approved blue companion, STYLE reference ONLY; never copy its wings, face or blue palette to this subject.
Primary request: redraw the reference as polished clean cartoon 2D illustration. Clear dark colored contours, restrained cel shading, simple readable broad shapes and soft small highlights, same cohesive 2D rendering language as approved companion. No photorealism, no 3D render, no pixel filter.
Subject invariants observed from source: {desc}
Composition: {composition}
Scene/background: genuinely transparent RGBA, entire character visible with at least 8% margin, no ground shadow, no floor, no scenery, no ambient halo, no external particles except specific source floating elements.
Constraints: original silhouette and color blocking take precedence over fantasy embellishment; no redesign of original-complete subjects, no extra armor, horns, tails, limbs, accessories or eyes. Rear view must show rear, not mirrored front face. No captions, labels, watermarks, or source reference pasted into output. A single character asset, not a multi-character contact sheet.
'''
        (ROOT/j['folder']/'prompts/design.txt').write_text(prompt)
        j['observedConstraints']=desc
    write_json(OUT/'jobs.json',jobs)
    print('Prompts written:',len(jobs))


if __name__=='__main__':
    main()
